    base = {"nodes": 3, "zones": ["zone-a", "zone-b"]}
    tenant = {"zones": ["zone-b", "zone-c"]}
    manifest = build_cluster_spec("cls-1", base, tenant)
    zones = manifest.get_node_zones()
    assert zones == ["zone-a", "zone-b", "zone-c"]
